                    "sheet": tb.title,
                    "cell": total_cell.coordinate,
                    "year": year,
                    "factor": 1,
                    "sum_of": components,
                })

        for label, formula in (
            ("Net increase/(decrease) in cash", "net_change_in_cash"),
