            calculated[year] = values

        source_totals = []

        def add_total(sheet, label, formula):
            for year in ("cy", "py"):
                source_totals.append({
                    **reference(sheet, label, year),
                    "year": year,
                    "formula": formula,
                })

        printed_totals = {
            "IS": {
